import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOpenSans = makeLoadFont('OpenSans');

const { fontFamily } = loadOpenSans();



export type FlywheelExplainerProps = Record<string, any>;

const polarToCartesian = (
  cx: number,
  cy: number,
  r: number,
  angle: number
) => ({
  x: cx + r * Math.cos(angle),
  y: cy + r * Math.sin(angle),
});

const describeArc = (
  cx: number,
  cy: number,
  r: number,
  startAngle: number,
  endAngle: number
) => {
  if (Math.abs(endAngle - startAngle) < 0.001) return "";
  const start = polarToCartesian(cx, cy, r, startAngle);
  const end = polarToCartesian(cx, cy, r, endAngle);
  const diff = Math.abs(endAngle - startAngle);
  const largeArcFlag = diff <= Math.PI ? "0" : "1";
  const sweepFlag = endAngle > startAngle ? "1" : "0";
  return [
    "M", start.x, start.y,
    "A", r, r, 0, largeArcFlag, sweepFlag, end.x, end.y,
  ].join(" ");
};

const FlywheelExplainer: React.FC<FlywheelExplainerProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 10,
  direction = "counter-clockwise",
  accentColor = "#39FF14",
  textColor = "#FFFFFF",
  labels = [
    "Launch Ads",
    "Optimise For Highest ROAS (retargeting)",
    "Try & Scale",
    "Results Fall Off A Cliff",
    "Need New Creative"
  ],
  spinSpeed = 0.05,
  radiusScale = 0.25,
  textRadiusScale = 0.38,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const base = Math.min(width, height);
  const cx = width / 2;
  const cy = height / 2;
  const radius = base * radiusScale;
  const textRadius = base * textRadiusScale;

  const n = labels.length;
  const step = (Math.PI * 2) / n;
  const padding = Math.min(0.18, step * 0.2); // Dynamic gap to prevent elements overlapping

  const dir = direction === "clockwise" ? 1 : -1;
  const globalAngleOffset = (frame / fps) * spinSpeed * Math.PI * 2 * dir;
  const arrowSize = base * 0.008;
  const dotMaxRadius = base * 0.008;
  const strokeWidth = base * 0.004;
  const fontSize = Math.max(16, base * 0.024);
  const textContainerWidth = base * 0.35;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, transition: "none" }}>
      
      {/* SVG Layer for Connections & Nodes */}
      <svg
        width={width}
        height={height}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          pointerEvents: "none",
          filter: `drop-shadow(0px 0px 8px ${accentColor}66)`,
          transition: "none",
        }}
      >
        {labels.map((_, i) => {
          // Timing staggers
          const entryDelay = i * 15;
          const arcDelay = entryDelay + 5;

          const pNode = spring({
            fps,
            frame: frame - entryDelay,
            config: { damping: 12 },
          });

          const pArc = spring({
            fps,
            frame: frame - arcDelay,
            config: { damping: 16, mass: 0.8 },
          });

          // Math for Node position
          const baseAngle = i * step * dir;
          const actualAngle = baseAngle + globalAngleOffset;
          const dotPos = polarToCartesian(cx, cy, radius, actualAngle);

          // Math for Arc path
          const aStart = baseAngle + padding * dir + globalAngleOffset;
          const aEndMax = baseAngle + step * dir - padding * dir + globalAngleOffset;
          const aEnd = aStart + pArc * (aEndMax - aStart);
          const arcPath = describeArc(cx, cy, radius, aStart, aEnd);

          // Math for Arrowhead
          const tangentDeg = (aEnd + (Math.PI / 2) * dir) * (180 / Math.PI);
          const arrowPoint = polarToCartesian(cx, cy, radius, aEnd);

          return (
            <g key={`segment-${i}`} style={{ transition: "none" }}>
              {/* Arc */}
              {pArc > 0.01 && (
                <>
                  <path
                    d={arcPath}
                    fill="none"
                    stroke={accentColor}
                    strokeWidth={strokeWidth}
                    strokeLinecap="round"
                    style={{ transition: "none" }}
                  />
                  {/* Arrowhead */}
                  <g
                    transform={`translate(${arrowPoint.x}, ${arrowPoint.y}) rotate(${tangentDeg})`}
                    style={{ transition: "none" }}
                  >
                    <polygon
                      points={`-${arrowSize},-${arrowSize} ${arrowSize},0 -${arrowSize},${arrowSize}`}
                      fill={accentColor}
                      style={{ transition: "none" }}
                    />
                  </g>
                </>
              )}
              {/* Node Dot */}
              <circle
                cx={dotPos.x}
                cy={dotPos.y}
                r={dotMaxRadius * pNode}
                fill="#ffffff"
                style={{ transition: "none" }}
              />
            </g>
          );
        })}
      </svg>

      {/* HTML Layer for Upright Text */}
      {labels.map((label, i) => {
        const entryDelay = i * 15;
        const pNode = spring({
          fps,
          frame: frame - entryDelay,
          config: { damping: 12 },
        });

        const textOpacity = interpolate(
          frame - entryDelay - 5,
          [0, 15],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        const baseAngle = i * step * dir;
        const actualAngle = baseAngle + globalAngleOffset;
        const txtPos = polarToCartesian(cx, cy, textRadius, actualAngle);

        return (
          <div
            key={`label-${i}`}
            style={{
              position: "absolute",
              left: txtPos.x,
              top: txtPos.y,
              transform: "translate(-50%, -50%)",
              opacity: textOpacity,
              scale: `${0.8 + 0.2 * pNode}`,
              color: textColor,
              fontSize,
              fontWeight: "bold",
              textAlign: "center",
              width: textContainerWidth,
              lineHeight: 1.4,
              textShadow: "0px 2px 8px rgba(0,0,0,0.9)",
              pointerEvents: "none",
              transition: "none",
            }}
          >
            {label}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default FlywheelExplainer;